
'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='estudalab.redacao.v1',HKEY='estudalab.redacao.history.v1';
const TOPICS=[{"id":"edu1","category":"Educação","title":"Estratégias para combater o abandono escolar no Brasil","texts":[{"label":"TEXTO I · PANORAMA","body":"A permanência na escola depende de transporte, alimentação, acolhimento e condições concretas de estudo."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Um adolescente que precisa trabalhar para complementar a renda familiar pode ver a frequência escolar como uma escolha impossível."},{"label":"TEXTO III · REFLEXÃO","body":"Políticas de permanência precisam considerar desigualdades de renda, trajetórias individuais e a qualidade da experiência escolar."}]},{"id":"edu2","category":"Educação","title":"Caminhos para ampliar o acesso à leitura na sociedade brasileira","texts":[{"label":"TEXTO I · PANORAMA","body":"Bibliotecas e livros digitais ampliam possibilidades, mas acesso a obras não significa necessariamente formação de leitores."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Em bairros sem equipamentos culturais, a biblioteca da escola pode ser o único espaço público de leitura."},{"label":"TEXTO III · REFLEXÃO","body":"Formação docente, mediação de leitura e circulação de acervos podem estimular o hábito além das atividades avaliativas."}]},{"id":"edu3","category":"Educação","title":"Desafios da inclusão de estudantes com deficiência na escola","texts":[{"label":"TEXTO I · PANORAMA","body":"Matrícula não garante participação efetiva se materiais, espaços e práticas pedagógicas não forem acessíveis."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Uma aula que depende de recursos visuais sem adaptação pode excluir alunos mesmo dentro da sala."},{"label":"TEXTO III · REFLEXÃO","body":"A inclusão exige acessibilidade, formação de profissionais e respeito às necessidades de cada estudante."}]},{"id":"edu4","category":"Educação","title":"Desigualdade de acesso à educação digital no Brasil","texts":[{"label":"TEXTO I · PANORAMA","body":"Tecnologias educacionais podem apoiar a aprendizagem, mas seu benefício depende de conexão e de equipamentos disponíveis."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Alunos que dividem um único celular em casa enfrentam dificuldades distintas das de quem possui computador e internet estável."},{"label":"TEXTO III · REFLEXÃO","body":"O acesso digital precisa ser acompanhado de formação e de materiais que também funcionem sem conexão constante."}]},{"id":"edu5","category":"Educação","title":"Os desafios da alfabetização na idade adequada","texts":[{"label":"TEXTO I · PANORAMA","body":"Aprender a ler envolve linguagem, contato com textos e oportunidades de acompanhamento individual."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Dificuldades não identificadas nos primeiros anos podem se acumular e afetar todas as disciplinas seguintes."},{"label":"TEXTO III · REFLEXÃO","body":"Avaliação contínua, apoio pedagógico e parceria com famílias são caminhos complementares."}]},{"id":"edu6","category":"Educação","title":"Caminhos para valorizar a carreira docente no Brasil","texts":[{"label":"TEXTO I · PANORAMA","body":"A aprendizagem é influenciada pela formação, pelo tempo de planejamento e pelas condições de trabalho de professores."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Quando faltam recursos e profissionais, atividades de apoio e acompanhamento se tornam mais difíceis."},{"label":"TEXTO III · REFLEXÃO","body":"Valorização inclui carreira, formação continuada, segurança e infraestrutura, não apenas homenagens simbólicas."}]},{"id":"saú1","category":"Saúde","title":"Desafios da saúde mental de jovens no Brasil","texts":[{"label":"TEXTO I · PANORAMA","body":"Adolescentes convivem com pressão por desempenho, mudanças sociais e exposição contínua a ambientes digitais."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"O medo do julgamento pode dificultar que estudantes procurem ajuda, mesmo quando existem serviços disponíveis."},{"label":"TEXTO III · REFLEXÃO","body":"Apoio psicológico, redes de confiança e acesso a serviços são dimensões diferentes da prevenção."}]},{"id":"saú2","category":"Saúde","title":"Desafios de acesso à atenção primária à saúde","texts":[{"label":"TEXTO I · PANORAMA","body":"Unidades básicas são a porta de entrada para prevenção, acompanhamento e identificação precoce de doenças."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Quem mora longe do atendimento ou enfrenta longas filas pode adiar consultas importantes."},{"label":"TEXTO III · REFLEXÃO","body":"Acesso exige distribuição territorial, equipes suficientes, informação e continuidade do cuidado."}]},{"id":"saú3","category":"Saúde","title":"O combate à desinformação sobre vacinas","texts":[{"label":"TEXTO I · PANORAMA","body":"Decisões de saúde pública dependem de informações confiáveis e de confiança nas instituições."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Boatos compartilhados em redes podem parecer convincentes mesmo quando omitem contexto ou evidências."},{"label":"TEXTO III · REFLEXÃO","body":"Comunicação clara, profissionais acessíveis e educação científica ajudam a enfrentar dúvidas legítimas."}]},{"id":"saú4","category":"Saúde","title":"Envelhecimento da população e redes de cuidado","texts":[{"label":"TEXTO I · PANORAMA","body":"O aumento da longevidade traz necessidades de acompanhamento, mobilidade e participação social."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Famílias podem assumir cuidados intensos sem orientação nem rede comunitária de apoio."},{"label":"TEXTO III · REFLEXÃO","body":"Serviços públicos, adaptações urbanas e apoio a cuidadores contribuem para envelhecer com dignidade."}]},{"id":"saú5","category":"Saúde","title":"Desafios de prevenção da obesidade infantil","texts":[{"label":"TEXTO I · PANORAMA","body":"A alimentação é influenciada por preço, publicidade, tempo das famílias e oferta nos territórios."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Uma criança pode ter recomendações nutricionais, mas viver em região com opções saudáveis mais caras e escassas."},{"label":"TEXTO III · REFLEXÃO","body":"Prevenção exige ambientes alimentares melhores, atividade física e respeito à saúde sem estigmatização."}]},{"id":"saú6","category":"Saúde","title":"Saúde da mulher e acesso a cuidados preventivos","texts":[{"label":"TEXTO I · PANORAMA","body":"Exames, orientação e acompanhamento dependem de informação e de serviços disponíveis de modo contínuo."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Barreiras de deslocamento e horários de atendimento podem impedir consultas mesmo quando elas são gratuitas."},{"label":"TEXTO III · REFLEXÃO","body":"Ampliar equipes, acolhimento e prevenção requer considerar diferentes realidades de vida."}]},{"id":"tec1","category":"Tecnologia e mídia","title":"Desafios para combater a desinformação digital no Brasil","texts":[{"label":"TEXTO I · PANORAMA","body":"A circulação veloz de conteúdos em plataformas digitais favorece tanto a informação útil quanto mensagens manipuladas."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Uma postagem sem fonte pode atingir milhares de pessoas antes de qualquer verificação e influenciar decisões relevantes."},{"label":"TEXTO III · REFLEXÃO","body":"Educação midiática, transparência e responsabilidade das plataformas são caminhos que precisam preservar liberdades."}]},{"id":"tec2","category":"Tecnologia e mídia","title":"Uso ético da inteligência artificial na educação","texts":[{"label":"TEXTO I · PANORAMA","body":"Ferramentas de IA podem auxiliar na explicação de conteúdos, mas também gerar respostas incorretas com aparência de certeza."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Se um aluno entrega um texto produzido integralmente por máquina, pode obter uma nota sem desenvolver a própria argumentação."},{"label":"TEXTO III · REFLEXÃO","body":"O desafio é criar critérios de uso que favoreçam aprendizagem, autoria e avaliação crítica."}]},{"id":"tec3","category":"Tecnologia e mídia","title":"Proteção de dados pessoais de crianças e adolescentes","texts":[{"label":"TEXTO I · PANORAMA","body":"Aplicativos e sites coletam informações sobre hábitos, localização aproximada e preferências de usuários."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Um adolescente pode aceitar permissões sem compreender como seus dados serão utilizados por terceiros."},{"label":"TEXTO III · REFLEXÃO","body":"Privacidade digital envolve responsabilidade de empresas, orientação familiar e letramento tecnológico."}]},{"id":"tec4","category":"Tecnologia e mídia","title":"Desafios da violência virtual entre adolescentes","texts":[{"label":"TEXTO I · PANORAMA","body":"Ataques e humilhações online podem continuar fora do horário escolar e alcançar públicos numerosos."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Uma imagem compartilhada sem consentimento pode ser replicada mesmo após a exclusão da postagem original."},{"label":"TEXTO III · REFLEXÃO","body":"Educação para convivência digital e mecanismos de acolhimento e denúncia devem caminhar juntos."}]},{"id":"tec5","category":"Tecnologia e mídia","title":"A exclusão de idosos no acesso a serviços digitais","texts":[{"label":"TEXTO I · PANORAMA","body":"Bancos e serviços públicos oferecem cada vez mais tarefas por aplicativos e plataformas."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Uma pessoa sem familiaridade com interfaces digitais pode depender de terceiros para exercer direitos simples."},{"label":"TEXTO III · REFLEXÃO","body":"Canais presenciais, interfaces acessíveis e apoio de aprendizagem são parte da inclusão."}]},{"id":"tec6","category":"Tecnologia e mídia","title":"Impactos dos algoritmos na formação de opiniões","texts":[{"label":"TEXTO I · PANORAMA","body":"Sistemas de recomendação selecionam conteúdos com base em sinais de interesse e engajamento."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Quem recebe repetidamente um único tipo de posicionamento pode ter menos contato com perspectivas divergentes."},{"label":"TEXTO III · REFLEXÃO","body":"Diversidade informacional, transparência e pensamento crítico ajudam a formar escolhas mais autônomas."}]},{"id":"mei1","category":"Meio ambiente","title":"Caminhos para reduzir o desperdício de alimentos no Brasil","texts":[{"label":"TEXTO I · PANORAMA","body":"Alimentos podem se perder na produção, no transporte, no comércio e dentro das residências."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Uma feira pode descartar produtos ainda próprios para consumo por questões de aparência ou logística."},{"label":"TEXTO III · REFLEXÃO","body":"Planejamento, informação, doação responsável e estrutura de armazenamento são medidas complementares."}]},{"id":"mei2","category":"Meio ambiente","title":"Desafios para ampliar o saneamento básico nas cidades brasileiras","texts":[{"label":"TEXTO I · PANORAMA","body":"Água tratada, esgoto e manejo de resíduos impactam diretamente a saúde e o ambiente."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Bairros sem coleta de esgoto convivem com maior exposição a doenças e degradação de rios e córregos."},{"label":"TEXTO III · REFLEXÃO","body":"Investimentos continuados e fiscalização precisam alcançar áreas historicamente negligenciadas."}]},{"id":"mei3","category":"Meio ambiente","title":"Desafios da gestão de resíduos eletrônicos","texts":[{"label":"TEXTO I · PANORAMA","body":"Celulares, baterias e computadores contêm materiais reutilizáveis e substâncias que exigem descarte adequado."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Sem pontos de coleta próximos, aparelhos antigos podem acabar misturados ao lixo doméstico."},{"label":"TEXTO III · REFLEXÃO","body":"Logística reversa, reparabilidade e informação ao consumidor ajudam a reduzir danos."}]},{"id":"mei4","category":"Meio ambiente","title":"Mudanças climáticas e proteção de comunidades vulneráveis","texts":[{"label":"TEXTO I · PANORAMA","body":"Eventos extremos têm efeitos diferentes conforme moradia, renda, infraestrutura e capacidade de resposta local."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Chuvas intensas podem afetar de forma desproporcional famílias que vivem em encostas e áreas sujeitas a alagamentos."},{"label":"TEXTO III · REFLEXÃO","body":"Prevenção exige mapeamento de risco, moradia segura e serviços de alerta acessíveis."}]},{"id":"mei5","category":"Meio ambiente","title":"O uso responsável da água nos centros urbanos","texts":[{"label":"TEXTO I · PANORAMA","body":"O abastecimento envolve captação, tratamento, distribuição e consumo cotidiano."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Vazamentos nas redes e desigualdades de acesso mostram que economizar água não depende apenas de hábitos individuais."},{"label":"TEXTO III · REFLEXÃO","body":"Manutenção de infraestrutura e gestão sustentável devem acompanhar a conscientização."}]},{"id":"mei6","category":"Meio ambiente","title":"Preservação da biodiversidade nos biomas brasileiros","texts":[{"label":"TEXTO I · PANORAMA","body":"Biomas abrigam espécies e processos ecológicos que sustentam serviços ambientais e atividades humanas."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"A fragmentação de habitats dificulta a circulação de animais e compromete relações entre espécies."},{"label":"TEXTO III · REFLEXÃO","body":"Proteção territorial, pesquisa e alternativas produtivas sustentáveis precisam ser articuladas."}]},{"id":"dir1","category":"Direitos e inclusão","title":"Obstáculos à inclusão de pessoas com deficiência no mercado de trabalho","texts":[{"label":"TEXTO I · PANORAMA","body":"Acessibilidade não é apenas presença de rampas: envolve comunicação, processos seletivos e condições reais de trabalho."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Uma pessoa qualificada pode ser barrada por seleção inacessível ou por expectativas discriminatórias."},{"label":"TEXTO III · REFLEXÃO","body":"Contratação, adaptação razoável e cultura organizacional inclusiva são etapas distintas."}]},{"id":"dir2","category":"Direitos e inclusão","title":"Desafios no combate ao racismo estrutural no Brasil","texts":[{"label":"TEXTO I · PANORAMA","body":"Desigualdades raciais podem aparecer no acesso a oportunidades e no tratamento recebido em instituições."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Uma regra aparentemente igual para todos pode produzir resultados desiguais quando as condições iniciais são distintas."},{"label":"TEXTO III · REFLEXÃO","body":"Enfrentar o problema exige diagnóstico, educação antirracista e políticas de igualdade de oportunidades."}]},{"id":"dir3","category":"Direitos e inclusão","title":"A valorização dos povos indígenas na sociedade brasileira","texts":[{"label":"TEXTO I · PANORAMA","body":"Povos indígenas possuem histórias, culturas e conhecimentos diversos, muitas vezes reduzidos a estereótipos."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"A ausência de participação das comunidades em decisões que as afetam compromete o reconhecimento de seus direitos."},{"label":"TEXTO III · REFLEXÃO","body":"Escuta, proteção de territórios e valorização de línguas e saberes devem orientar as políticas."}]},{"id":"dir4","category":"Direitos e inclusão","title":"Caminhos para enfrentar a violência contra a mulher","texts":[{"label":"TEXTO I · PANORAMA","body":"A violência pode assumir formas físicas, psicológicas, patrimoniais e digitais."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Uma vítima sem renda, rede de apoio ou informação pode enfrentar dificuldades para romper um ciclo de agressões."},{"label":"TEXTO III · REFLEXÃO","body":"Proteção efetiva combina atendimento, prevenção, acesso à justiça e autonomia econômica."}]},{"id":"dir5","category":"Direitos e inclusão","title":"Inclusão social de pessoas em situação de rua","texts":[{"label":"TEXTO I · PANORAMA","body":"A vida nas ruas pode resultar de processos interligados de pobreza, desemprego e rompimentos familiares."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Sem endereço e documentação, tarefas como buscar emprego ou atendimento podem se tornar ainda mais difíceis."},{"label":"TEXTO III · REFLEXÃO","body":"Políticas de moradia, saúde e reinserção precisam respeitar a dignidade e a autonomia dessas pessoas."}]},{"id":"dir6","category":"Direitos e inclusão","title":"Acessibilidade cultural para pessoas com deficiência","texts":[{"label":"TEXTO I · PANORAMA","body":"Participar de atividades culturais é parte do direito à vida social e ao lazer."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Um museu sem audiodescrição ou sinalização acessível pode oferecer entrada gratuita, mas não experiência inclusiva."},{"label":"TEXTO III · REFLEXÃO","body":"Recursos de acessibilidade e participação das pessoas com deficiência no planejamento mudam a qualidade do acesso."}]},{"id":"tra1","category":"Trabalho e economia","title":"Desafios da qualificação profissional para jovens","texts":[{"label":"TEXTO I · PANORAMA","body":"A transição escola-trabalho exige competências técnicas, orientação e oportunidades de primeira experiência."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"A exigência de experiência em vagas iniciais pode dificultar o ingresso de quem ainda está se formando."},{"label":"TEXTO III · REFLEXÃO","body":"Estágios supervisionados, ensino técnico e orientação de carreira podem aproximar formação e mercado."}]},{"id":"tra2","category":"Trabalho e economia","title":"Impactos da automação nas profissões brasileiras","texts":[{"label":"TEXTO I · PANORAMA","body":"Máquinas e softwares assumem tarefas repetitivas, ao mesmo tempo que surgem atividades diferentes."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Um trabalhador experiente pode precisar atualizar competências para continuar participando de seu setor."},{"label":"TEXTO III · REFLEXÃO","body":"Qualificação continuada e proteção na transição tecnológica ajudam a distribuir benefícios."}]},{"id":"tra3","category":"Trabalho e economia","title":"A valorização do trabalho doméstico e de cuidados","texts":[{"label":"TEXTO I · PANORAMA","body":"Cuidar de crianças, idosos e da casa demanda tempo, energia e organização, mesmo quando não recebe salário."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"A sobrecarga de cuidados pode limitar oportunidades de estudo e trabalho remunerado."},{"label":"TEXTO III · REFLEXÃO","body":"Políticas de apoio e divisão mais equilibrada das responsabilidades tornam esse trabalho visível."}]},{"id":"tra4","category":"Trabalho e economia","title":"Educação financeira na adolescência","texts":[{"label":"TEXTO I · PANORAMA","body":"Crédito digital, parcelamentos e compras por aplicativos fazem parte do cotidiano de muitos jovens."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Sem compreender juros, um consumidor pode contratar uma dívida que cresce mais rápido do que imaginava."},{"label":"TEXTO III · REFLEXÃO","body":"A escola pode ensinar planejamento, consumo crítico e leitura de contratos sem moralismo."}]},{"id":"tra5","category":"Trabalho e economia","title":"Desafios da informalidade no mercado de trabalho","texts":[{"label":"TEXTO I · PANORAMA","body":"Atividades informais podem ser fonte de renda, mas frequentemente apresentam proteção social limitada."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Trabalhadores com renda instável podem enfrentar obstáculos para planejar despesas e enfrentar emergências."},{"label":"TEXTO III · REFLEXÃO","body":"Caminhos incluem simplificação, acesso a direitos e políticas de geração de renda."}]},{"id":"tra6","category":"Trabalho e economia","title":"O empreendedorismo como alternativa para jovens brasileiros","texts":[{"label":"TEXTO I · PANORAMA","body":"Criar pequenos negócios pode ampliar autonomia, mas envolve riscos, informação e acesso a recursos."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"A abertura de uma loja virtual parece simples, porém logística, impostos e divulgação exigem planejamento."},{"label":"TEXTO III · REFLEXÃO","body":"Formação em gestão e acesso responsável a crédito podem reduzir vulnerabilidades iniciais."}]},{"id":"cul1","category":"Cultura e patrimônio","title":"Desafios da valorização da cultura popular brasileira","texts":[{"label":"TEXTO I · PANORAMA","body":"Expressões populares preservam memórias e formas de convivência em diferentes regiões do país."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Grupos culturais podem manter tradições vivas sem conseguir espaços adequados para apresentar seu trabalho."},{"label":"TEXTO III · REFLEXÃO","body":"Financiamento, educação patrimonial e participação das comunidades ajudam a sustentar essas manifestações."}]},{"id":"cul2","category":"Cultura e patrimônio","title":"A importância da preservação de patrimônios históricos","texts":[{"label":"TEXTO I · PANORAMA","body":"Edificações, objetos e lugares preservam narrativas que ajudam a compreender a história coletiva."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Um espaço histórico abandonado perde funções culturais e pode deixar de ser reconhecido pela população local."},{"label":"TEXTO III · REFLEXÃO","body":"Preservação demanda manutenção e usos públicos que aproximem patrimônio e comunidade."}]},{"id":"cul3","category":"Cultura e patrimônio","title":"Desigualdade de acesso ao cinema e ao teatro","texts":[{"label":"TEXTO I · PANORAMA","body":"Produções culturais circulam por salas, centros comunitários, escolas e plataformas digitais."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Famílias que moram longe de equipamentos culturais enfrentam gastos de transporte e oferta reduzida."},{"label":"TEXTO III · REFLEXÃO","body":"Circuitos regionais, escolas e iniciativas itinerantes ampliam oportunidades de participação."}]},{"id":"cul4","category":"Cultura e patrimônio","title":"Representatividade na produção audiovisual brasileira","texts":[{"label":"TEXTO I · PANORAMA","body":"Filmes e séries contribuem para a percepção pública de diferentes grupos sociais."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Quando personagens são retratados sempre pelo mesmo estereótipo, suas experiências reais ficam simplificadas."},{"label":"TEXTO III · REFLEXÃO","body":"Diversidade de profissionais, narrativas e distribuição pode enriquecer a produção cultural."}]},{"id":"cul5","category":"Cultura e patrimônio","title":"O papel das bibliotecas públicas na cidadania","texts":[{"label":"TEXTO I · PANORAMA","body":"Bibliotecas podem ser espaços de leitura, acesso à informação, estudo e convivência."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Uma biblioteca com acervo rico, mas horários incompatíveis com a rotina da comunidade, atende menos pessoas."},{"label":"TEXTO III · REFLEXÃO","body":"Políticas culturais devem pensar também em localização, horários e mediação de acesso."}]},{"id":"cul6","category":"Cultura e patrimônio","title":"A difusão de saberes de comunidades tradicionais","texts":[{"label":"TEXTO I · PANORAMA","body":"Conhecimentos sobre território, alimentos e técnicas são transmitidos entre gerações."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Sem reconhecimento e participação, saberes coletivos podem ser apropriados ou ignorados em decisões importantes."},{"label":"TEXTO III · REFLEXÃO","body":"Valorizar esses conhecimentos exige diálogo, proteção e respeito aos protagonistas."}]},{"id":"cid1","category":"Cidadania e política","title":"Desafios da participação política dos jovens brasileiros","texts":[{"label":"TEXTO I · PANORAMA","body":"Participação democrática inclui debates, associações, voluntariado e acompanhamento de decisões públicas."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Jovens podem se interessar por problemas coletivos, mas sentir que suas opiniões não chegam aos espaços de decisão."},{"label":"TEXTO III · REFLEXÃO","body":"Educação cívica e canais de participação acessíveis ajudam a transformar interesse em ação responsável."}]},{"id":"cid2","category":"Cidadania e política","title":"A importância da transparência nos serviços públicos","texts":[{"label":"TEXTO I · PANORAMA","body":"Informações claras sobre gastos, contratos e resultados permitem controle social."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Um cidadão pode ter direito à informação, mas encontrar páginas difíceis de navegar e dados incompreensíveis."},{"label":"TEXTO III · REFLEXÃO","body":"Transparência também depende de linguagem acessível e mecanismos de fiscalização."}]},{"id":"cid3","category":"Cidadania e política","title":"O fortalecimento do voluntariado no Brasil","texts":[{"label":"TEXTO I · PANORAMA","body":"Ações voluntárias podem apoiar comunidades e aproximar pessoas de problemas locais."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Projetos dependentes de poucos participantes podem enfrentar dificuldades de continuidade e organização."},{"label":"TEXTO III · REFLEXÃO","body":"Formação, parcerias e reconhecimento ajudam a tornar iniciativas sustentáveis."}]},{"id":"cid4","category":"Cidadania e política","title":"Combate à corrupção e cultura de integridade","texts":[{"label":"TEXTO I · PANORAMA","body":"Integridade pública envolve regras, fiscalização e decisões transparentes em diferentes níveis."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Pequenas práticas de favorecimento podem normalizar comportamentos que prejudicam o interesse coletivo."},{"label":"TEXTO III · REFLEXÃO","body":"Controles institucionais e educação ética precisam atuar de forma complementar."}]},{"id":"cid5","category":"Cidadania e política","title":"A garantia do direito à documentação civil","texts":[{"label":"TEXTO I · PANORAMA","body":"Documentos permitem acesso a serviços, trabalho, educação e participação cidadã."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Uma pessoa sem registro adequado pode ter dificuldade para acessar direitos básicos, mesmo estando formalmente previstos."},{"label":"TEXTO III · REFLEXÃO","body":"Atendimento itinerante e simplificação de procedimentos contribuem para inclusão."}]},{"id":"cid6","category":"Cidadania e política","title":"O papel da educação midiática na democracia","texts":[{"label":"TEXTO I · PANORAMA","body":"Discussões públicas dependem de acesso a informações verificáveis e pluralidade de perspectivas."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Mensagens sensacionalistas podem mobilizar emoções antes de oferecer elementos para análise."},{"label":"TEXTO III · REFLEXÃO","body":"Ensinar checagem de fontes e diferenciação entre fato e opinião fortalece o debate democrático."}]},{"id":"mob1","category":"Cidades e mobilidade","title":"Desafios para assegurar o direito à moradia digna","texts":[{"label":"TEXTO I · PANORAMA","body":"Moradia envolve segurança, infraestrutura, acesso a serviços e vínculos com a comunidade."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Uma casa distante do trabalho e sem transporte eficiente pode gerar novas formas de vulnerabilidade."},{"label":"TEXTO III · REFLEXÃO","body":"Planejamento urbano e políticas habitacionais devem considerar qualidade e localização."}]},{"id":"mob2","category":"Cidades e mobilidade","title":"Caminhos para melhorar o transporte público brasileiro","texts":[{"label":"TEXTO I · PANORAMA","body":"Linhas, frequência, tarifa e integração influenciam o acesso ao estudo e ao trabalho."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Uma pessoa que depende de várias conexões perde horas diariamente, mesmo em trajetos relativamente curtos."},{"label":"TEXTO III · REFLEXÃO","body":"Melhorias exigem planejamento de redes, acessibilidade e participação dos usuários."}]},{"id":"mob3","category":"Cidades e mobilidade","title":"Desafios da mobilidade de pessoas com deficiência","texts":[{"label":"TEXTO I · PANORAMA","body":"Calçadas, travessias e veículos acessíveis determinam a possibilidade de circular pela cidade."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Uma rampa pode ser inútil quando está bloqueada por obstáculos ou termina em calçada irregular."},{"label":"TEXTO III · REFLEXÃO","body":"Acessibilidade urbana precisa ser contínua, não composta de adaptações isoladas."}]},{"id":"mob4","category":"Cidades e mobilidade","title":"Enfrentamento das enchentes em centros urbanos","texts":[{"label":"TEXTO I · PANORAMA","body":"Impermeabilização do solo e ocupação de áreas de risco influenciam os danos provocados por chuvas intensas."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Após temporais, famílias podem perder documentos, móveis e acesso a serviços essenciais."},{"label":"TEXTO III · REFLEXÃO","body":"Obras de drenagem, prevenção territorial e planos de emergência precisam caminhar juntos."}]},{"id":"mob5","category":"Cidades e mobilidade","title":"Desafios da segurança viária no Brasil","texts":[{"label":"TEXTO I · PANORAMA","body":"Trânsito seguro depende de infraestrutura, fiscalização e comportamento dos usuários."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Uma rua projetada para alta velocidade pode tornar travessias perigosas para pedestres e ciclistas."},{"label":"TEXTO III · REFLEXÃO","body":"Desenho urbano seguro e educação no trânsito reduzem vulnerabilidades."}]},{"id":"mob6","category":"Cidades e mobilidade","title":"A importância dos espaços públicos de lazer","texts":[{"label":"TEXTO I · PANORAMA","body":"Praças e parques favorecem encontro comunitário, atividade física e convivência."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Bairros sem sombra, iluminação ou manutenção podem ter áreas livres que quase ninguém utiliza."},{"label":"TEXTO III · REFLEXÃO","body":"Planejamento inclusivo e conservação tornam o lazer mais acessível."}]},{"id":"juv1","category":"Juventude e sociedade","title":"A pressão estética sobre adolescentes nas redes sociais","texts":[{"label":"TEXTO I · PANORAMA","body":"Conteúdos filtrados e padrões idealizados podem influenciar a percepção sobre o próprio corpo."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Comparações constantes podem transformar uma experiência digital em fonte de ansiedade e insatisfação."},{"label":"TEXTO III · REFLEXÃO","body":"Educação midiática e valorização da diversidade ajudam a reduzir cobranças irreais."}]},{"id":"juv2","category":"Juventude e sociedade","title":"Desafios da prevenção ao bullying nas escolas","texts":[{"label":"TEXTO I · PANORAMA","body":"Bullying envolve agressões repetidas e desequilíbrio de poder, com efeitos sobre convivência e aprendizagem."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Quando uma turma trata humilhações como brincadeira, vítimas podem evitar pedir ajuda."},{"label":"TEXTO III · REFLEXÃO","body":"Prevenção exige protocolos de acolhimento, mediação e participação de toda a comunidade escolar."}]},{"id":"juv3","category":"Juventude e sociedade","title":"O impacto do isolamento social nas relações juvenis","texts":[{"label":"TEXTO I · PANORAMA","body":"Laços de amizade e pertencimento são importantes durante a formação da identidade."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Uma pessoa com muitos contatos digitais pode, ainda assim, sentir falta de convivência e apoio presencial."},{"label":"TEXTO III · REFLEXÃO","body":"Espaços de encontro, escuta e participação ajudam a fortalecer vínculos."}]},{"id":"juv4","category":"Juventude e sociedade","title":"Desafios do uso excessivo de telas na adolescência","texts":[{"label":"TEXTO I · PANORAMA","body":"O tempo de tela reúne atividades muito diferentes, do estudo ao lazer e à comunicação."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Notificações constantes podem interromper concentração e descanso, mesmo quando os conteúdos são úteis."},{"label":"TEXTO III · REFLEXÃO","body":"Rotinas equilibradas e alfabetização digital são alternativas melhores do que respostas simplistas."}]},{"id":"juv5","category":"Juventude e sociedade","title":"A participação das famílias no percurso escolar","texts":[{"label":"TEXTO I · PANORAMA","body":"O acompanhamento escolar assume formas diversas conforme trabalho, renda e disponibilidade dos responsáveis."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Famílias interessadas na aprendizagem nem sempre conseguem comparecer a reuniões em horários fixos."},{"label":"TEXTO III · REFLEXÃO","body":"Comunicação flexível e acolhimento aproximam escola e responsáveis."}]},{"id":"juv6","category":"Juventude e sociedade","title":"A valorização de projetos de vida na juventude","texts":[{"label":"TEXTO I · PANORAMA","body":"Projetos pessoais se constroem entre interesses, oportunidades e condições socioeconômicas."},{"label":"TEXTO II · SITUAÇÃO-PROBLEMA","body":"Escolhas profissionais podem parecer individuais, mas são condicionadas por oferta de cursos, renda e redes de apoio."},{"label":"TEXTO III · REFLEXÃO","body":"Orientação e ampliação de oportunidades ajudam jovens a planejar com autonomia."}]}];
const temas=[...TOPICS.map(t=>t.title),'Personalizar tema…'];
const writing=EstudaLabWritingCore;
const draftStore=writing.createStore(localStorage,temas[0]);
let ui=draftStore.active();
const titles={introducao:'Introdução',d1:'Desenvolvimento 1',d2:'Desenvolvimento 2',conclusao:'Conclusão'};
let lastSnapshot=0;
function drafts(snapshot=false){const now=Date.now(),take=snapshot||now-lastSnapshot>60000;const ok=draftStore.save(ui,take,now);if(take&&ok)lastSnapshot=now;$('#save-status').textContent=ok?'Rascunho salvo neste navegador.':'Não foi possível salvar. Copie seu texto antes de sair.';return ok}
function currentTopic(){return ui.tema==='Personalizar tema…'?ui.customTema.trim():ui.tema}
function textValue(){return writing.text(ui)}
const words=writing.words;
function switchTopic(tema){if(!drafts(true)){$('#tema').value=ui.tema;return false;}ui=draftStore.get(tema);$('#tema').value=tema;$('#tema-custom').value=ui.customTema;$('#modo').value=ui.modo;renderEditor();renderEditorThemePreview();return true}
function setTab(tab){$$('[data-tab]').forEach(x=>x.setAttribute('aria-selected',String(x.dataset.tab===tab)));['temas','aprender','treinar','simulado','progresso'].forEach(id=>$('#'+id).hidden=id!==tab);if(tab==='temas')renderTopics();if(tab==='treinar')renderEditorThemePreview();if(tab==='progresso')renderHistory();if(tab==='simulado')renderQuiz();if(location.hash!=='#'+tab){history.pushState(null,'','#'+tab);window.scrollTo({top:0,behavior:'instant'})}shell.setRoute(tab,({temas:'Biblioteca de temas',aprender:'Como escrever',treinar:'Editor de redação',simulado:'Simulados',progresso:'Histórico de redações'})[tab]);document.querySelector('#subject-content > .hero').hidden=tab!=='temas';document.title='Redação · EstudaLab'}
$$('[data-tab]').forEach(x=>x.addEventListener('click',()=>setTab(x.dataset.tab)));
if(ui.tema&&!temas.includes(ui.tema))temas.splice(0,0,ui.tema);
$('#tema').innerHTML=temas.map(t=>`<option value="${escapeHTML(t)}" ${t===ui.tema?'selected':''}>${t==='Personalizar tema…'?'Tema livre — escreva seu tema':escapeHTML(t)}</option>`).join('');$('#modo').value=ui.modo;$('#tema-custom').value=ui.customTema;
function renderEditor(){
 const chosen=$('#modo').value;ui.modo=chosen;$('#custom-area').hidden=ui.tema!=='Personalizar tema…';
 const parts=chosen==='completa'?['completa']:[chosen];
 $('#editor').innerHTML=parts.map(p=>`<div class="field"><label for="text-${p}">${p==='completa'?'Redação completa':titles[p]}</label><textarea id="text-${p}" data-part="${p}" maxlength="12000" spellcheck="true" placeholder="${p==='completa'?'Escreva ou cole sua redação completa aqui. Separe os parágrafos com uma linha em branco.':p==='introducao'?'Apresente o problema, contextualize e formule sua tese…':p==='conclusao'?'Desenvolva uma intervenção ligada ao problema discutido…':'Apresente o argumento, explique e relacione à tese…'}">${escapeHTML(p==='completa'?writing.text({...ui,modo:'completa'}):ui.campos[p]||'')}</textarea></div>`).join('');
 if(chosen==='completa')$('#editor').insertAdjacentHTML('beforeend','<p class="muted">O texto completo e os treinos de trechos ficam salvos separadamente. Na primeira abertura, reunimos seus trechos para você continuar.</p>');
 $$('textarea[data-part]').forEach(t=>t.addEventListener('input',()=>{if(t.dataset.part==='completa')ui.textoCompleto=t.value;else ui.campos[t.dataset.part]=t.value;drafts();updateWordCount();$('#result').hidden=true}));
 updateWordCount();drafts();$('#result').hidden=true;$('#loading').textContent='';
}
function updateWordCount(){$('#words').textContent=words(textValue())+' palavras';}
$('#free-topic').addEventListener('click',()=>{if(!switchTopic('Personalizar tema…'))return;$('#modo').value='completa';renderEditor();setTab('treinar');$('#tema-custom').focus();$('#custom-area').scrollIntoView({block:'center'})});
$('#consent').addEventListener('change',()=>{$('#correct').textContent=$('#consent').checked?'Corrigir com IA':'Revisar sem IA'});
$('#modo').addEventListener('change',()=>{drafts(true);renderEditor()});
$('#tema').addEventListener('change',e=>switchTopic(e.target.value));
$('#tema-custom').addEventListener('input',e=>{ui.customTema=e.target.value;drafts();renderEditorThemePreview()});renderEditor();
$('#save-version').addEventListener('click',()=>{if(drafts(true))$('#save-status').textContent='Versão guardada no histórico de rascunhos.'});
$('#clear').addEventListener('click',()=>{if(!confirm('Limpar esta parte? Uma versão ficará guardada no histórico.'))return;if(!drafts(true))return;if(ui.modo==='completa')ui.textoCompleto='';else ui.campos[ui.modo]='';renderEditor()});
$('#sample').addEventListener('click',()=>{const examples={introducao:'Na sociedade brasileira, a circulação de conteúdos enganosos nas plataformas digitais compromete decisões individuais e coletivas. Nesse contexto, a insuficiência da educação midiática e a baixa responsabilização dos difusores de notícias falsas agravam o problema, exigindo medidas coordenadas.',d1:'Em primeiro lugar, a falta de educação midiática favorece a disseminação de informações falsas. Isso ocorre porque usuários sem formação para verificar fontes compartilham publicações sem avaliar sua confiabilidade, ampliando a circulação de conteúdos enganosos. Assim, o déficit educacional compromete escolhas informadas.',d2:'Além disso, mecanismos pouco transparentes de distribuição de conteúdo podem impulsionar materiais sensacionalistas. Quando o alcance depende apenas de engajamento, publicações enganosas podem obter grande visibilidade. Por isso, critérios de transparência são necessários.',conclusao:'Portanto, o Ministério da Educação, em parceria com redes estaduais e municipais, deve oferecer oficinas de leitura crítica de mídias nas escolas, por meio de formação continuada de docentes e materiais didáticos verificados, a fim de reduzir o compartilhamento de desinformação entre estudantes. As ações devem incluir exercícios de checagem de fontes e avaliação semestral de aprendizagem.'};const p=ui.modo==='completa'?'introducao':ui.modo;alert('EXEMPLO DIDÁTICO (não copie na prova):\n\n'+examples[p]+'\n\nAdapte ao tema selecionado e construa argumentos próprios.');});
function localAnalysis(text,modo){return writing.structural(text,modo)}
function renderFeedback(res,mode){
 const ai=res.origem==='ia',partial=mode!=='completa',validScore=ai&&!partial&&Number.isFinite(res.nota)&&['C1','C2','C3','C4','C5'].every(k=>Number.isFinite(res.competencias?.[k]));
 const score=validScore?`<div class="result-score">${res.nota}<small>/1000</small></div><p class="muted">Estimativa pedagógica por IA. Não é uma nota oficial e pode conter erros.</p><div class="score-list">${Object.entries(res.competencias).filter(([k])=>/^C[1-5]$/.test(k)).map(([k,v])=>`<div class="score-box"><small>${k}</small><strong>${v}</strong><small>de 200</small></div>`).join('')}</div>`:'';
 const justification=validScore?`<h3>Por que cada competência recebeu essa pontuação</h3>${Object.entries(res.justificativas||{}).map(([k,v])=>`<details class="feedback"><summary>${escapeHTML(k)} · ${res.competencias[k]}/200</summary><p>${escapeHTML(v.analise)}</p>${(v.evidencias||[]).map(t=>`<blockquote>${escapeHTML(t)}</blockquote>`).join('')}<p><strong>Desconto: ${escapeHTML(v.desconto)} pontos.</strong> ${escapeHTML(v.motivoDesconto)}</p>${v.ausencia?`<p>${escapeHTML(v.ausencia)}</p>`:''}${v.incerteza?`<p class="muted">${escapeHTML(v.incerteza)}</p>`:''}</details>`).join('')}`:'';
 $('#result').innerHTML=`<div class="rule"></div><div class="eyebrow">${ai?'Leitura assistida por IA':'Revisão estrutural · sem nota'}</div><h2 class="mini-title">Seu próximo passo na escrita</h2>${score}<p>${escapeHTML(res.resumo)}</p>${justification}${ai?`<h3>Elementos examinados</h3><div class="check-grid">${Object.entries(res.checklist||{}).map(([k,v])=>`<span class="check ${v?'yes':'no'}">${v?'Identificado':'Revisar'}: ${escapeHTML(({tese:'tese',topico:'tópico frasal',argumentacao:'argumentação',coesao:'coesão',agente:'agente',acao:'ação',meio:'meio',finalidade:'finalidade',detalhamento:'detalhamento'}[k]||k))}</span>`).join('')}</div>`:''}${(res.falhas||[]).length?'<h3>Trechos para revisar</h3>':''}${(res.falhas||[]).map(v=>`<div class="feedback"><h4>${escapeHTML(v.problema)}</h4>${v.trecho?`<blockquote>${escapeHTML(v.trecho)}</blockquote>`:''}<p>${escapeHTML(v.comoMelhorar)}</p></div>`).join('')}${(res.forcas||[]).length?`<h3>Pontos que funcionam</h3><ul>${res.forcas.map(v=>`<li>${escapeHTML(v)}</li>`).join('')}</ul>`:''}${(res.perguntas||[]).length?`<h3>Perguntas para sua revisão</h3><p class="muted">Responda ao reler o texto. Estes itens não são um diagnóstico automático.</p><ul>${res.perguntas.map(v=>`<li>${escapeHTML(v)}</li>`).join('')}</ul>`:''}${(res.acoes||[]).length?`<h3>Ações sugeridas</h3><ol>${res.acoes.map(v=>`<li>${escapeHTML(v)}</li>`).join('')}</ol>`:''}<p class="muted">${(res.alertas||[]).map(escapeHTML).join(' · ')}</p>`;
 $('#result').hidden=false;$('#result').scrollIntoView({behavior:'smooth',block:'start'});
}
$('#correct').addEventListener('click',async()=>{
 const texto=textValue(),tema=currentTopic(),modo=ui.modo;
 if(tema.length<8||tema.length>300)return alert('Escreva um tema entre 8 e 300 caracteres.');
 if(texto.length<70||texto.length>12000)return alert('O texto deve ter entre 70 e 12.000 caracteres.');
 drafts(true);const campos={...ui.campos},textoCompleto=ui.textoCompleto;const btn=$('#correct');btn.disabled=true;$('#loading').textContent='Lendo seu texto…';let res;
 try{
  if(!$('#consent').checked){res=localAnalysis(texto,modo);$('#loading').textContent='Revisão local concluída. O texto não foi enviado.'}
  else{const abort=new AbortController(),timer=setTimeout(()=>abort.abort(),35000);let response;try{response=await fetch('/api/corrigir',{method:'POST',headers:{'Content-Type':'application/json'},signal:abort.signal,body:JSON.stringify({tema,modo,texto})})}finally{clearTimeout(timer)}
   if(!response.ok){const e=await response.json().catch(()=>({}));throw Error(e.erro||'Serviço de correção indisponível.')}
   res=await response.json();$('#loading').textContent='Leitura por IA concluída. Confira as evidências e os limites da análise.';
  }
 }catch(e){res=localAnalysis(texto,modo);$('#loading').textContent=`${e.name==='AbortError'?'O serviço demorou além do limite.':e.message} Exibindo revisão estrutural local, sem nota.`}
 finally{btn.disabled=false}
 renderFeedback(res,modo);if(textValue()!==texto||currentTopic()!==tema)$('#loading').textContent='Esta análise se refere à versão enviada, guardada no histórico. Seu rascunho atual foi mantido.';
 try{const raw=JSON.parse(localStorage.getItem(HKEY)||'[]'),h=Array.isArray(raw)?raw:[];h.unshift({id:Date.now().toString(36),at:new Date().toISOString(),tema,modo,campos,textoCompleto,texto,origem:res.origem,nota:res.nota??null,resumo:res.resumo,feedback:res});localStorage.setItem(HKEY,JSON.stringify(h.slice(0,40)))}catch{$('#loading').textContent+=' O histórico não pôde ser salvo; copie o texto.'}
});
function getHistory(){try{const h=JSON.parse(localStorage.getItem(HKEY)||'[]');return Array.isArray(h)?h.filter(x=>x&&typeof x.tema==='string'):[]}catch{return []}}
function renderHistory(){
 const h=getHistory(),list=draftStore.list();
 $('#draft-history').innerHTML=list.length?list.map((d,i)=>`<details class="feedback"><summary>${escapeHTML(d.tema==='Personalizar tema…'?d.customTema||'Tema personalizado':d.tema)}</summary><p>${words(writing.text({...d,modo:'completa'}))} palavras · ${d.updatedAt?new Date(d.updatedAt).toLocaleString('pt-BR'):'rascunho anterior'}</p><button class="btn secondary" data-draft="${i}">Retomar rascunho</button>${d.versions.map((v,j)=>`<button class="btn secondary" data-draft="${i}" data-version="${j}">Versão de ${new Date(v.at).toLocaleString('pt-BR')}</button>`).join('')}</details>`).join(''):'<p>Nenhum rascunho guardado.</p>';
 $('#history').innerHTML=h.length?h.map((x,i)=>`<details class="feedback"><summary>${escapeHTML(titles[x.modo]||'Redação completa')} · ${escapeHTML(new Date(x.at).toLocaleDateString('pt-BR'))} · ${escapeHTML(x.tema)}</summary><p>${x.origem==='ia'?'Leitura por IA':'Revisão estrutural'}${Number.isFinite(x.nota)?' · estimativa '+x.nota+'/1000':' · sem nota'}</p><p>${escapeHTML(x.resumo)}</p>${x.texto?`<pre class="writing-saved-text">${escapeHTML(x.texto)}</pre><button class="btn secondary" data-history="${i}">Abrir este treino</button>`:''}</details>`).join(''):'<p class="muted">Nenhum treino revisado ainda.</p>';
}
$('#draft-history').addEventListener('click',e=>{const b=e.target.closest('[data-draft]');if(!b)return;const d=draftStore.list()[Number(b.dataset.draft)];if(!d||!drafts(true))return;ui=writing.clean(b.dataset.version===undefined?d:d.versions[Number(b.dataset.version)]);syncEditor();setTab('treinar')});
function syncEditor(){if(!temas.includes(ui.tema))temas.unshift(ui.tema);$('#tema').innerHTML=temas.map(t=>`<option value="${escapeHTML(t)}" ${t===ui.tema?'selected':''}>${t==='Personalizar tema…'?'Tema livre — escreva seu tema':escapeHTML(t)}</option>`).join('');$('#modo').value=ui.modo;$('#tema-custom').value=ui.customTema;renderEditor();renderEditorThemePreview()}
$('#history').addEventListener('click',e=>{const b=e.target.closest('[data-history]');if(!b)return;const h=getHistory()[Number(b.dataset.history)];if(!h||!drafts(true))return;ui=writing.clean(h);syncEditor();setTab('treinar');if(h.feedback)renderFeedback(h.feedback,h.modo)});
$('#wipe-history').addEventListener('click',()=>{if(confirm('Apagar o histórico de correções? Os rascunhos serão mantidos.')){try{localStorage.removeItem(HKEY);renderHistory()}catch{alert('Não foi possível apagar o histórico.')}}});
