/* EstudaLab: question variety engine (stable across attempts). */
function writingArea(q){
  const t=q[0].toLowerCase();
  if(/interven|conclus|agente|detalh|finalidade|medida|proposta|meio\/modo/.test(t))return 'Proposta de intervenção';
  if(/competência i |norma|concord|pontua|ortograf|crase|gramát|revisar c1/.test(t))return 'Norma-padrão';
  if(/conect|coesão|embora|entretanto|portanto|por conseguinte|além disso/.test(t))return 'Coesão';
  if(/repertório|citação|tema|referência|recorte|desinformação/.test(t))return 'Tema e repertório';
  return 'Argumentação';
}
function renderQuiz(){$('#quiz-app').innerHTML=EstudaLabStudyUI.quizHTML('redacao',[...BANK,...EXTRA_BANK_V7].map(q=>({legacyId:q[0],topic:writingArea(q),prompt:q[0],options:q[1],answer:q[2],explanation:q[3]})),{label:'Redação',legacyNamespace:'redacao',onComplete:hits=>{try{localStorage.setItem('estudalab.redacao.quizbest',String(Math.max(Number(localStorage.getItem('estudalab.redacao.quizbest')||0),hits)))}catch{}}})}
